function user(){if(window.DemoAuth?.publicGuest)return {id:'GUEST',name:'Registration visitor',role:'Trainee',projects:[]};return db.users.find(x=>x.id===active)||db.users[0]}function central(){return user()?.role===roles[0]}function trainer(){return user()?.role===roles[4]}function trainee(){return user()?.role===roles[5]}function visibleProject(p){return central()||user()?.projects?.includes(p.id)}function projects(){return db.projects.filter(visibleProject)}function batches(){let u=user();return db.batches.filter(b=>projects().some(p=>p.id===b.project)&&(context==='all'||b.project===context)&&(!u.state||db.schools.find(s=>s.id===b.school)?.state===u.state)&&(!u.school||b.school===u.school)&&(!trainer()||b.trainer===u.trainer)&&(!trainee()||db.trainees.some(t=>t.id===u.trainee&&t.batch===b.id)))}function uniquePlanCode(){let code;do{code=uid('TP')}while(db.plans.some(p=>R.norm(p.code)===R.norm(code)));return code}function planUsed(id){return db.batches.some(b=>b.plan===id)}function plans(){let u=user();return db.plans.filter(p=>projects().some(x=>x.id===p.project)&&(context==='all'||p.project===context)&&(!(trainer()||trainee())||batches().some(b=>b.plan===p.id)))}function trainees(){return db.trainees.filter(t=>batches().some(b=>b.id===t.batch)&&(!trainee()||t.id===user().trainee))}function canManageBatches(b){return (central()||(roles.slice(1,4).includes(user()?.role)&&user().batchManage===true))&&(!b||!b.id||batches().some(x=>x.id===b.id))}function batchCandidateAllowed(b){let u=user(),school=db.schools.find(s=>s.id===b.school);return projects().some(p=>p.id===b.project)&&(context==='all'||context===b.project)&&(!u.state||school?.state===u.state)&&(!u.school||b.school===u.school)}function canBatch(b){return !!b&&batches().some(x=>x.id===b.id)&&(canManageBatches(b)||(trainer()&&b.trainer===user().trainer))}function lookup(arr,id,key='name'){return arr.find(x=>x.id===id)?.[key]||'—'}function mask(v){return v?'•••'+String(v).slice(-3):'—'}function nameMask(t){return t?'Trainee '+t.id.slice(0,10):'—'}function message(s,error=false){$id('message').textContent=s;$id('message').className=error?'error':''}function deny(){message('You do not have permission to perform this action in this scope.',true)}
function redact(v){if(Array.isArray(v))return v.map(redact);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,['name','mobile','email','password'].includes(k)?mask(x):redact(x)]));return v}function visibleAudit(a){if(central()||a.actor===active)return true;if(trainer()||trainee()||!projects().some(p=>p.id===a.project))return false;let batch=a.after?.batch||a.before?.batch||db.batches.find(b=>b.id===a.entity)?.id||db.trainees.find(t=>t.id===a.entity)?.batch;return !batch||batches().some(b=>b.id===batch)}function audit(action,entity,before,after,project){before=redact(before);after=redact(after);db.audit.push({id:uid('AUD'),date:new Date().toISOString(),actor:active,action,entity,project:project||context,before,after})}function commit(fn,text){let prev=JSON.stringify(db);try{fn();localStorage.setItem(KEY,JSON.stringify(db));message(text||'Changes saved in this browser.');return true}catch(e){db=JSON.parse(prev);message('Changes were not saved: '+e.message+' Browser storage may be full or blocked.',true);return false}}
function activity(type,result){commit(()=>db.activity.push({date:new Date().toISOString(),user:active,type,result}),'Demo activity recorded.')}function options(arr,value,key='name',blank=true){return (blank?'<option value="">Select…</option>':'')+arr.map(x=>'<option value="'+esc(x.id)+'"'+(x.id===value?' selected':'')+'>'+esc(x[key])+'</option>').join('')}function btn(label,action,id='',cls=''){return '<button type="button" class="btn '+cls+'" data-action="'+action+'" data-id="'+esc(id)+'">'+label+'</button>'}function badge(s){return '<span class="pill">'+esc(s)+'</span>'}function info(s,w=false){return '<div class="info '+(w?'warning':'')+'">'+s+'</div>'}function table(headers,rows){if(!rows.length)return '<div class="empty">No records are available in this scope or filter.</div>';return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}function head(title,sub,actions=''){return '<div class="page-head"><div><div class="eyebrow">TRAINING WORKSPACE / '+esc(current.toUpperCase())+'</div><h1>'+title+'</h1><p class="sub">'+sub+'</p></div><div class="actions">'+actions+'</div></div>'}function panel(title,body){return '<section class="panel"><h2>'+title+'</h2>'+body+'</section>'}function searchBar(){return '<div class="toolbar"><label for="tableSearch">Search this table</label><input id="tableSearch" type="search" placeholder="Search visible records"></div>'}function selectBatch(){return '<div class="toolbar"><label for="batchSelect">Batch</label><select id="batchSelect">'+options(batches(),sessionStorage.getItem('reviewBatch'), 'code')+'</select></div>'}function selectedBatch(){let id=$id('batchSelect')?.value||sessionStorage.getItem('reviewBatch');return batches().find(b=>b.id===id)||batches()[0]}function status(b){return b.closed?'Completed':today<b.start?'Upcoming':today>b.end?'Awaiting completion':'In Progress'}function statPct(m){return m.length?Math.round(100*m.filter(x=>x.status==='Present').length/m.length)+'%':'N/A'}function effectiveLinks(b){return db.links.filter(l=>R.linkEffective(l,b,db.settings))}function accessible(r,b){let p=db.projects.find(x=>x.id===b.project);let links=effectiveLinks(b).filter(l=>l.resource===r.id);return links.some(l=>(!r.formType&&!l.days?.length)||(l.days||[]).some(d=>today>=R.add(b.start,d-1)))&&today<=p.end}function canUploadResources(){return central()||(trainer()&&(user().resourceUpload??db.settings.trainerUpload))}function resourcePlans(){return central()?plans():plans().filter(p=>batches().some(b=>b.plan===p.id))}function resourceProjects(){return projects().filter(p=>resourcePlans().some(pl=>pl.project===p.id))}function resourceScope(){return db.resources.filter(r=>r.common||projects().some(p=>p.id===r.project)&&(context==='all'||r.project===context)||db.links.some(l=>l.resource===r.id&&plans().some(p=>p.id===l.plan))).filter(r=>!(trainer()||trainee())||(trainer()&&(r.uploadedBy===active||r.common&&canUploadResources()))||batches().some(b=>effectiveLinks(b).some(l=>l.resource===r.id)))}
function syncHeader(){let ps=projects();if(ps.length===1)context=ps[0].id;else if(context!=='all'&&!ps.some(p=>p.id===context))context='all';$id('projectContext').innerHTML=(ps.length>1?'<option value="all">All permitted projects</option>':'')+options(ps,context,'name',false);$id('projectContext').value=context;$id('persona').innerHTML=options(db.users.map(u=>({id:u.id,name:u.id+' · '+(u.role==='Trainee'?'Trainee Teacher / Student':u.role)})),active,'name',false);$id('identity').textContent='User ID: '+(user()?.id||'')+' · '+(user()?.name||'')+' · '+(user()?.role==='Trainee'?'Trainee Teacher / Student':user()?.role||'');let signed=window.DemoAuth?.session()?.mode==='login';$id('persona').disabled=!!signed||!!window.DemoAuth?.publicGuest;$id('persona').setAttribute('title',signed?'Login role is fixed. Logout to switch users.':'Demo persona · not authentication');$id('signout').textContent='Logout';$id('nav').innerHTML=nav.filter(([id])=>!window.DemoAuth||window.DemoAuth.allowed(user()?.role,id)).map(([id,icon,label])=>'<a href="'+pageHref(id)+'" class="'+(current===id?'active':'')+'"'+(current===id?' aria-current="page"':'')+'><span class="nav-icon" aria-hidden="true">'+icon+'</span>'+label+'</a>').join('')}
