function bars(obj){let max=Math.max(1,...Object.values(obj));return Object.keys(obj).length?Object.entries(obj).map(([k,v])=>'<div class="bar-row"><span>'+esc(k)+'</span><div class="bar"><span style="width:'+(v/max*100)+'%"></span></div><strong>'+v+'</strong></div>').join(''):'<div class="empty">No data available.</div>'}function formCompletion(ts,kind){let expected=0,done=0;for(let t of ts){let b=db.batches.find(b=>b.id===t.batch);for(let l of effectiveLinks(b)){let resource=db.resources.find(r=>r.id===l.resource);if(resource?.formType&&(!kind||resource.formType===kind)){expected++;if(db.submissions.some(s=>s.trainee===t.id&&s.resource===l.resource))done++}}}return expected?Math.round(done/expected*100)+'%'+(kind?'':' combined'):'N/A'}
function roleDetail(bs,ts,marks){let u=user();if(trainee()){let t=ts[0],b=bs[0];if(!t||!b)return '<div class="empty">No training assigned.</div>';let done=db.attendance.filter(a=>a.trainee===t.id&&a.status==='Present').length;return '<p>My training: '+esc(lookup(db.plans,b.plan))+' · '+esc(lookup(db.schools,b.school,'location'))+' · '+esc(lookup(db.trainers,b.trainer))+'</p><p>Present evidence: '+done+' of '+lookup(db.plans,b.plan,'days')+' plan days. Completion remains conditional.</p><div class="actions"><a class="btn" href="#assessments">Today’s assessments & feedback</a><a class="btn" href="#resources">Learning resources</a><a class="btn" href="#attendance">My attendance</a><a class="btn" href="#certificates">My certificate</a></div>'}if(trainer())return table(['Today’s batch','Trainees','Attendance pending','Assessment / feedback'],bs.filter(b=>today>=b.start&&today<=b.end).map(b=>[esc(b.code),ts.filter(t=>t.batch===b.id).length,ts.filter(t=>t.batch===b.id&&!marks.some(a=>a.date===today&&a.trainee===t.id)).length,formCompletion(ts.filter(t=>t.batch===b.id))]));return '<p>Total schools: '+new Set(bs.map(b=>b.school)).size+' · Upcoming: '+bs.filter(b=>today<b.start).length+' · Ongoing: '+bs.filter(b=>today>=b.start&&today<=b.end&&!b.closed).length+' · Completed: '+bs.filter(b=>b.closed).length+'</p><p>Registration/approval pending: '+ts.filter(t=>!t.approved).length+' · Assessment / feedback: '+formCompletion(ts)+' · Recorded attendance: '+statPct(marks)+'</p>'+info('Completion/certification percentages, trainer utilization and threshold alerts require approved definitions.')}function filter(id,label,arr){return '<div><label for="'+id+'">'+label+'</label><select id="'+id+'">'+options(arr,'','name',true).replace('Select…','All')+'</select></div>'}function uniqueSchools(k){return [...new Set(db.schools.filter(s=>batches().some(b=>b.school===s.id)).map(s=>s[k]))].map(n=>({id:n,name:n}))}
