function formHTML(kind,data,fields,label='Save locally'){return '<form id="editForm" data-kind="'+kind+'" novalidate><input type="hidden" name="id" value="'+esc(data.id||'')+'"><input type="hidden" name="batch" value="'+esc(data.batch||'')+'"><div class="form-grid">'+fields.map(f=>field(f[0],f[1],f[2],data[f[0]]??'',f[3],f[4])).join('')+'</div><div id="formError" class="invalid-feedback" role="alert"></div><div class="form-actions"><button type="submit" class="btn btn-primary">'+label+'</button></div></form>'}
function modal(title,body){$id('dialogTitle').textContent=title;$id('dialogBody').innerHTML=body;if(!$id('editor').open)$id('editor').showModal()}function closeModal(){$id('editor').close();dialogForm=null;stage=null;masterStage=null}function errors(e){document.querySelectorAll('.invalid-feedback').forEach(x=>x.textContent='');document.querySelectorAll('.is-invalid').forEach(x=>x.classList.remove('is-invalid'));for(let[k,msg]of Object.entries(e)){let f=$id('f-'+k),m=$id('e-'+k);if(m)m.textContent=msg;else if($id('formError'))$id('formError').textContent=msg;if(f){f.classList.add('is-invalid');f.setAttribute('aria-invalid','true');f.setAttribute('aria-describedby','e-'+k)}}document.querySelector('.is-invalid')?.focus()}
