function fileStore(op,id,value){return new Promise((resolve,reject)=>{let req=indexedDB.open('training-tracker-files-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onerror=()=>reject(req.error);req.onsuccess=()=>{let database=req.result,tx=database.transaction('files',op==='get'?'readonly':'readwrite'),store=tx.objectStore('files'),r=op==='get'?store.get(id):op==='delete'?store.delete(id):op==='clear'?store.clear():store.put(value,id);let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>{database.close();resolve(result)};tx.onerror=()=>{database.close();reject(tx.error)};tx.onabort=()=>reject(tx.error||Error('File storage transaction aborted.'))}})}function readDataURL(f){return new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(f)})}function download(blob,name){let a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const batchCols=['Batch ID','Project Code','Training Plan Code','UDISE Code','Reference Location','Start Date','End Date','Maximum Size','Trainer Code','Open Registration'],traineeCols=['Batch ID','Name','Mobile','Email'];
function openImport(kind,id){let b=batches().find(b=>b.id===id);if(kind==='batches'?!canManageBatches():!canBatch(b))return deny();stage=null;dialogForm={kind:'import',type:kind,batch:id};modal('Import '+kind+' from Excel',info('Demo XLSX contract: first worksheet, named headers, dates as YYYY-MM-DD text or Excel serial dates. All rows validate before atomic save; no partial upload. Binary XLS and production size limits require clarification.')+'<div class="toolbar">'+btn('Download XLSX template','templateImport',kind)+'</div><label for="importFile">Excel workbook (.xlsx)</label><input id="importFile" type="file" accept=".xlsx"><div id="importPreview" role="status"></div><div class="form-actions">'+btn('Save validated import','commitImport','','btn-primary')+'</div>');document.querySelector('[data-action=commitImport]').disabled=true}
function dateValue(v){if(/^\d+(\.\d+)?$/.test(v)){let d=new Date(Date.UTC(1899,11,30)+Number(v)*86400000);return d.toISOString().slice(0,10)}return v}
async function parseImport(file){let setting=dialogForm;if(!file||setting?.kind!=='import')return;let view=$id('importPreview');view.innerHTML='<div class="loading">Parsing and validating workbook…</div>';document.querySelector('[data-action=commitImport]').disabled=true;try{let {headers,rows}=await Excel.read(file);if(dialogForm!==setting)return;let cols=setting.type==='batches'?batchCols:traineeCols,missing=cols.filter(h=>!headers.includes(h));if(missing.length)throw Error('Missing template columns: '+missing.join(', '));if(!rows.length)throw Error('The workbook contains no data rows.');let temp=structuredClone(db),results=[];for(let[rowIndex,r]of rows.entries()){let x,e;if(setting.type==='batches'){x={id:uid('B'),code:String(r['Batch ID']||'').trim(),project:temp.projects.find(p=>R.norm(p.code)===R.norm(r['Project Code']))?.id,plan:temp.plans.find(p=>R.norm(p.code)===R.norm(r['Training Plan Code']))?.id,school:temp.schools.find(s=>R.norm(s.udise)===R.norm(r['UDISE Code']))?.id,referenceLocation:r['Reference Location'],start:dateValue(r['Start Date']),end:dateValue(r['End Date']),capacity:Number(r['Maximum Size']),trainer:temp.trainers.find(t=>R.norm(t.code)===R.norm(r['Trainer Code']))?.id,open:/^yes$/i.test(String(r['Open Registration']||'').trim()),closed:false,created:new Date().toISOString()};e=R.batch(x,temp);if(!/^(yes|no)$/i.test(String(r['Open Registration']||'').trim()))e.open='Open Registration must be Yes or No (demo contract).';if(!batchCandidateAllowed(x))e.project='Project/school is outside permitted scope.';x.actualLocation=lookup(temp.schools,x.school,'location');if(!Object.keys(e).length)temp.batches.push(x)}else{let b=batches().find(b=>R.norm(b.code)===R.norm(r['Batch ID']));x={id:uid('U'),batch:b?.id,name:r.Name,mobile:r.Mobile,email:r.Email,approved:false,created:today};e=R.trainee(x,b,temp,false);if(!b||b.id!==setting.batch||!canBatch(b))e.batch='Row must refer to the selected permitted batch.';if(!Object.keys(e).length)temp.trainees.push(x)}results.push({row:rowIndex+2,data:x,errors:Object.values(e)})}stage={...setting,results};view.innerHTML=info(results.some(r=>r.errors.length)?'Validation failed. Nothing has been saved.':'All rows parsed and validated. Select Save validated import to persist.')+table(['Excel row','Identifier','UDISE actual location / batch','Validation'],results.map(r=>[r.row,esc(r.data.code||mask(r.data.name)),esc(stage.type==='batches'?r.data.actualLocation:lookup(db.batches,r.data.batch,'code')),r.errors.length?'<span class="invalid-feedback">'+esc(r.errors.join(' · '))+'</span>':badge('Valid')]));document.querySelector('[data-action=commitImport]').disabled=results.some(r=>r.errors.length)}catch(e){stage=null;view.innerHTML='<p class="invalid-feedback">'+esc(e.message)+'. Nothing has been saved.</p>'}}
async function commitImport(){if(!stage||stage.results.some(r=>r.errors.length)||uploadBusy)return;if(stage.type==='batches'?!canManageBatches():!canBatch(batches().find(b=>b.id===stage.batch)))return deny();let temp=structuredClone(db),e=[];for(let r of stage.results){let err=stage.type==='batches'?R.batch(r.data,temp):R.trainee(r.data,temp.batches.find(b=>b.id===r.data.batch),temp,false);if(stage.type==='batches'&&!batchCandidateAllowed(r.data))err.project='Project/school is outside permitted scope.';if(stage.type==='trainees'&&r.data.batch!==stage.batch)err.batch='Row must refer to the selected batch.';if(Object.keys(err).length)e.push(...Object.values(err));temp[stage.type==='batches'?'batches':'trainees'].push(r.data)}if(e.length){$id('importPreview').innerHTML=info('Data changed after preview; import not saved: '+esc(e.join(' · ')),true);return}uploadBusy=true;let records=stage.results.map(r=>r.data),type=stage.type;if(commit(()=>{db[type==='batches'?'batches':'trainees'].push(...records);for(let r of records)audit(type+' imported',r.id,null,type==='trainees'?{batch:r.batch,name:mask(r.name),mobile:mask(r.mobile),email:mask(r.email)}:r,r.project||db.batches.find(b=>b.id===r.batch)?.project)},records.length+' validated '+type+' records stored locally.')){closeModal();render()}uploadBusy=false}
async function importTemplate(kind){let cols=kind==='batches'?batchCols:traineeCols,b=db.batches.find(b=>b.id===(dialogForm?.batch||'B1'));let rows=kind==='batches'?[[uid('B-DEMO'),'ODOO-101','TP-DEMO-01','DEMO-UDISE-01','Sample reference',R.add(today,20),R.add(today,23),20,'TR-DEMO-01','No']]:[[b?.code||'B-DEMO-01','Sample New Teacher','9000000099','new.teacher@example.test']];download(await Excel.write(cols,rows),kind+'-template.xlsx');message('XLSX template generated and downloaded.')}
async function openResource(id){let r=resourceScope().find(r=>r.id===id);if(!r)return deny();let eligibleBatch=batches().find(b=>effectiveLinks(b).some(l=>l.resource===id)&&accessible(r,b));if(!central()&&!(trainer()&&r.uploadedBy===active)&&!eligibleBatch){modal('Resource availability',info('This activity is not available on this date, or is not linked to your permitted batch.',true));return}if(r.formType){modal('Form master',panel(esc(r.name),'<p>'+esc(r.question)+'</p>'+info('Submit through Assessments & feedback using the trainee persona.')));return}try{let blob=r.seed?new Blob(['SAMPLE classroom guide. Encourage participatory learning through discussion and reflection.'],{type:'text/plain'}):await fileStore('get',id);if(!blob)throw Error('File bytes are missing in this browser. Re-upload is required.');download(blob,r.seed?'sample-classroom-guide.txt':r.filename);commit(()=>{db.accesses.push({resource:id,user:active,date:new Date().toISOString()});audit('Resource accessed',id,null,{user:active},r.project)},'Resource bytes opened/downloaded; local access recorded.')}catch(e){message('Resource was not opened: '+e.message,true)}}
function certificateHTML(t){let b=db.batches.find(b=>b.id===t.batch),p=db.projects.find(p=>p.id===b.project),plan=db.plans.find(p=>p.id===b.plan),c=db.template,num='DEMO-'+t.id;return '<div class="cert" style="border-color:'+esc(c.color)+'">'+(c.organizationLogo?'<img alt="Organization logo" src="'+esc(c.organizationLogo)+'">':'')+(c.projectLogo?'<img alt="Project logo" src="'+esc(c.projectLogo)+'">':'')+'<p class="demo">DEMO PREVIEW · NOT AN ISSUED CERTIFICATE</p><h1>Certificate of Training</h1><p>'+esc(c.program)+' / '+esc(p.name)+'</p><p>This review preview recognizes</p><div class="name">'+esc(t.name)+'</div><p>Training: '+esc(plan.name)+'</p><p>Duration: '+plan.days+' days · Completion date: '+esc(b.end)+'</p><p>Certificate number: '+esc(num)+'</p><p>Authorized signatory: '+esc(c.signatory)+'</p><p class="meta">Eligibility uses provisional reviewer settings. Production issuance requires business sign-off.</p></div>'}
